<div class="quiz-container"><a class="text-link small muted" style="margin-bottom:22px" href="<?= e(route_url('/paths/' . (\Learnow\Repositories\DB::value('SELECT slug FROM learning_paths WHERE id=?',[$quiz['path_id']])))) ?>"><?= icon('arrow-left',15) ?> Back to my learning map</a>
<?php if(!$attempt): ?><section class="card quiz-intro"><span class="icon-tile purple"><?= icon('lightbulb',31) ?></span><span class="eyebrow orange-text" style="margin-bottom:12px">A LITTLE CHECK-IN WITH WHAT YOU KNOW</span><h1><?= e($quiz['title']) ?></h1><p><?= nl2br(e($quiz['instructions'])) ?></p><div class="quiz-facts"><div><strong><?= count($questions) ?></strong><span>questions</span></div><div><strong><?= (int)$quiz['passing_score'] ?>%</strong><span>to pass</span></div><div><strong><?= $quiz['time_limit_minutes']?(int)$quiz['time_limit_minutes'].' min':'Your pace' ?></strong><span><?= $quiz['time_limit_minutes']?'server-timed limit':'no time limit' ?></span></div></div><?php if($lives): ?><p><?= icon('heart',17) ?> <?= (int)$lives['remaining'] ?> of <?= (int)$lives['maximum'] ?> quiz lives available. Lessons remain open.</p><?php endif; ?><form action="<?= e(route_url('/api/quizzes/' . ((int)$quiz['id']) . '/start')) ?>" method="post" data-api><?= csrfField() ?><button class="btn btn-primary">Let’s see what’s clicking <?= icon('arrow-right',17) ?></button></form><p class="fine-print"><?= $quiz['attempt_limit']?(int)$quiz['attempt_limit'].' attempts allowed. '.count($attempts).' started so far.':'Retries are welcome. Only your first passing result earns this quiz’s XP.' ?><?php if(array_filter($questions,fn($q)=>$q['type']==='short')): ?><br>Written answers will be reviewed by an authorised reviewer.<?php endif; ?></p></section>
<?php elseif($attempt['status']==='in_progress'): ?><form id="quiz-form" action="<?= e(route_url('/api/attempts/' . ((int)$attempt['id']) . '/submit')) ?>" data-deadline="<?= $attempt['deadline_at']?e(gmdate('c',strtotime($attempt['deadline_at']))):'' ?>"><div class="quiz-top"><span data-question-label aria-live="polite">Question 1 of <?= count($questions) ?></span><span data-quiz-timer><?= $attempt['deadline_at']?'Timer loading…':'Take your time. You’ve got this.' ?></span></div><div class="progress-track"><span data-question-progress style="width:<?= 100/max(1,count($questions)) ?>%"></span></div><div class="card question-card"><div class="form-error" role="alert"></div><?php foreach($questions as $i=>$q): ?><section role="group" aria-labelledby="question-title-<?= (int)$q['id'] ?>" data-question="<?= (int)$q['id'] ?>" <?= $i?'hidden':'' ?>><span class="question-type"><?= e(match($q['type']){'multiple'=>'Choose all correct answers','short'=>'Written answer · manual review','boolean'=>'True or false',default=>'Choose one answer'}) ?> · <?= (int)$q['points'] ?> <?= $q['points']==1?'point':'points' ?></span><h2 id="question-title-<?= (int)$q['id'] ?>"><?= e($q['prompt']) ?></h2><?php if($q['type']==='short'): ?><div class="field"><label for="answer-<?= (int)$q['id'] ?>">Your explanation</label><textarea id="answer-<?= (int)$q['id'] ?>" maxlength="5000" placeholder="Explain it in your own words…" style="min-height:180px"></textarea></div><?php else: ?><div class="quiz-options"><?php foreach($q['options'] as $j=>$o): ?><label class="quiz-option"><input type="<?= $q['type']==='multiple'?'checkbox':'radio' ?>" name="question-<?= (int)$q['id'] ?>" value="<?= (int)$o['id'] ?>"><span><?= e($o['label']) ?></span><i class="quiz-option-letter"><?= chr(65+$j) ?></i></label><?php endforeach; ?></div><?php endif; ?></section><?php endforeach; ?><div class="quiz-navigation"><button type="button" class="btn btn-secondary" data-quiz-prev><?= icon('arrow-left',16) ?> Previous</button><button type="button" class="btn btn-primary" data-quiz-next>Next question <?= icon('arrow-right',16) ?></button><button type="submit" class="btn btn-primary" data-quiz-submit hidden>Submit my answers <?= icon('check',16) ?></button></div></div><div class="question-dots" aria-label="Question navigation"><?php foreach($questions as $i=>$q): ?><button type="button" class="question-dot" data-question-dot aria-label="Go to question <?= $i+1 ?>"><?= $i+1 ?></button><?php endforeach; ?></div><p class="fine-print centered">Answers are graded on the server. Submitted attempts cannot be edited.</p></form>
<?php else: ?><section class="card"><div class="quiz-intro"><?php if($attempt['status']==='pending_review'): ?><span class="icon-tile purple"><?= icon('message',29) ?></span><h1>A fresh pair of eyes is next.</h1><p>Your written answers are waiting for an authorised reviewer. Your final score and any earned rewards will appear after grading.</p><?php else: ?><div class="result-score <?= $attempt['status']==='failed'?'failed':'' ?>"><strong><?= round($attempt['score'],1) ?>%</strong><span><?= $attempt['status']==='passed'?'You passed!':'Keep growing.' ?></span></div><h1><?= $attempt['status']==='passed'?'That’s a little more confidence.':'Every attempt teaches you something.' ?></h1><p><?= $attempt['status']==='passed'?'Your result is saved. Take a moment to celebrate, then keep building on what you know.':'Review what you learned and revisit the lesson. A thoughtful retry is part of the process.' ?></p><?php endif; ?><div class="page-actions" style="justify-content:center"><a class="btn btn-secondary" href="<?= e(route_url('/paths/' . (\Learnow\Repositories\DB::value('SELECT slug FROM learning_paths WHERE id=?',[$quiz['path_id']])))) ?>">Back to my journey <?= icon('path',16) ?></a><?php if($attempt['status']==='failed' && (!$quiz['attempt_limit'] || count($attempts)<$quiz['attempt_limit'])): ?><form method="post" action="<?= e(route_url('/api/quizzes/' . ((int)$quiz['id']) . '/start')) ?>" data-api><?= csrfField() ?><button class="btn btn-primary">Give it another go <?= icon('arrow-right',16) ?></button></form><?php endif; ?></div></div>
<?php foreach($questions as $i=>$q): $r=$q['response']??null; ?><section class="answer-review <?= $r && $r['awarded_points']!==null?($r['awarded_points']==$q['points']?'correct':'incorrect'):'' ?>"><span class="answer-points"><?= $r && $r['awarded_points']!==null?e($r['awarded_points']).' / '.(int)$q['points']:'Review pending' ?></span><h3><?= $i+1 ?>. <?= e($q['prompt']) ?></h3><?php if($r): ?><?php if($q['type']==='short'): ?><p><strong>Your response:</strong> <?= nl2br(e($r['answer_text']?:'No response provided.')) ?></p><?php else: $selected=\Learnow\Repositories\DB::all('SELECT o.label FROM quiz_response_options ro JOIN answer_options o ON o.id=ro.option_id WHERE ro.response_id=?',[$r['id']]); ?><p><strong>Your answer:</strong> <?= e($selected?implode('; ',array_column($selected,'label')):'Not answered.') ?></p><?php endif; ?><?php if($r['feedback']): ?><p><strong>Reviewer feedback:</strong> <?= e($r['feedback']) ?></p><?php endif; ?><?php endif; ?><?php if($quiz['show_answers'] && isset($q['correct'])): ?><?php if($q['correct']): ?><p><strong>Correct answer<?= count($q['correct'])>1?'s':'' ?>:</strong> <?= e(implode('; ',array_column($q['correct'],'label'))) ?></p><?php endif; ?><p><?= e($q['explanation']) ?></p><?php endif; ?></section><?php endforeach; ?></section><?php endif; ?>
<?php if($attempts && (!$attempt || $attempt['status']!=='in_progress')): ?><section class="card card-pad" style="margin-top:24px"><div class="card-header"><h2>Your learning, recorded.</h2></div><div class="mini-list"><?php foreach($attempts as $a): ?><a class="mini-list-item" href="<?= e(route_url('/quizzes/' . ((int)$quiz['id']) . '?attempt=' . ((int)$a['id']))) ?>"><span class="icon-tile purple"><?= icon('file',18) ?></span><div><strong>Attempt #<?= (int)$a['id'] ?></strong><small><?= niceDate($a['submitted_at']??$a['started_at'],'M j, Y · H:i') ?> UTC</small></div><?= badge($a['status']) ?><strong style="font-size:12px"><?= $a['score']!==null?round($a['score']).'%':'—' ?></strong></a><?php endforeach; ?></div></section><?php endif; ?></div>
